require "rails_helper"

RSpec.describe "Timekeeping handoff round trip of a monolith checkpoint" do
  include_context "timekeeping entry writes without transactional fixtures"

  let(:round_trip_service_token) { "service-#{SecureRandom.hex(24)}" }

  around do |example|
    with_timekeeping_env(
      Timekeeping::Environment::TOKEN_PUBLIC_KEY => rsa_key_pair.public_key.to_pem,
      Timekeeping::Environment::SERVICE_TOKEN => round_trip_service_token
    ) { example.run }
  end

  # Acceptance: "Populated audits, idempotency receipts and operation receipts
  # round-trip between the two stores unchanged"
  it "loads the monolith store's populated checkpoint and exports its audits, receipts and operation receipts unchanged" do
    monolith_json = File.read(Rails.root.join("../spec/fixtures/files/timekeeping_handoff/monolith_checkpoint.json"))
    source = Timekeeping::Handoff::Checkpoint.from_json(monolith_json)
    %w[entry_audits idempotency_records invoice_operations].each do |table|
      expect(source.rows.fetch(table)).not_to be_empty, "the monolith checkpoint has no #{table} rows"
    end
    expect(source.rows.values.flatten.map { |row| row["company_id"] }.uniq.size).to be >= 2
    expect(Timekeeping::Handoff::Checkpoint.verify(source)).to be_empty

    Timekeeping::Admission.ensure_initial!
    Timekeeping::Admission.fence!
    headers = { "Authorization" => "Bearer #{round_trip_service_token}", "Content-Type" => "application/json" }

    put "/internal/v1/handoff/checkpoint", params: monolith_json, headers: headers
    expect(response.status).to eq(200)

    get "/internal/v1/handoff/checkpoint", headers: headers
    expect(response.status).to eq(200)
    exported = Timekeeping::Handoff::Checkpoint.from_json(response.body)

    expect(exported.digest).to eq(source.digest)
    Timekeeping::Handoff::Checkpoint::TABLES.each_key do |table|
      expect(exported.rows.fetch(table).map(&:to_a).sort_by(&:to_s))
        .to eq(source.rows.fetch(table).map(&:to_a).sort_by(&:to_s)), "#{table} rows changed in the round trip"
    end
  end
end

require "rails_helper"

RSpec.describe "Timekeeping handoff checkpoint export" do
  include_context "timekeeping entry writes without transactional fixtures"

  let(:export_service_token) { "service-#{SecureRandom.hex(24)}" }

  around do |example|
    with_timekeeping_env(
      Timekeeping::Environment::TOKEN_PUBLIC_KEY => rsa_key_pair.public_key.to_pem,
      Timekeeping::Environment::SERVICE_TOKEN => export_service_token
    ) { example.run }
  end

  # Acceptance: "Timekeeping exports its entries, reservations, invoice operations,
  # audit rows and idempotency receipts in the canonical checkpoint row shape, each row with company_id"
  it "exports every checkpoint table in the canonical shape with each row under its own company_id" do
    now = Time.utc(2026, 3, 2, 9)
    [11, 22].each do |company_id|
      entry = Entry.create!(company_id:, project_id: 5, user_id: 6, work_date: Date.new(2026, 3, 2), duration: 30.0,
                            bill_status: "unbilled", created_at: now, updated_at: now)
      AuditEvent.create!(company_id:, entry_id: entry.id, actor_type: "user", actor_id: 6, action: "create",
                         before: nil, after: { "duration" => 30.0 }, entry_created_at: now, created_at: now)
      IdempotencyReceipt.create!(company_id:, actor_type: "user", actor_id: 6, operation: "create", key: "k-#{company_id}",
                                 fingerprint: "f", status: 201, body: "{}", created_at: now)
    end

    get "/internal/v1/handoff/checkpoint", headers: { "Authorization" => "Bearer #{export_service_token}" }

    expect(response.status).to eq(200)
    checkpoint = Timekeeping::Handoff::Checkpoint.from_json(response.body)
    expect(checkpoint.rows.keys).to match_array(Timekeeping::Handoff::Checkpoint::TABLES.keys)
    expect(Timekeeping::Handoff::Checkpoint.verify(checkpoint)).to be_empty
    %w[entries entry_audits idempotency_records].each do |table|
      expect(checkpoint.rows.fetch(table).map { |row| row["company_id"] }).to contain_exactly(11, 22)
    end
    checkpoint.rows.each_value do |rows|
      rows.each { |row| expect(row["company_id"]).to be_a(Integer) }
    end
  end
end
